-- 2026-10-24 回填 users.registered_at（真正的注册时间）。
--
-- 背景：历史 users 表没有 created_at，注册时间一直写在 banend；但 banend 会被
-- 封禁/解封改写（改成 now+天数 / now-1h），导致按 banend 发周年勋章时漏发。
--
-- 取值优先级（取最早的可信时间）：
--   1) 2026-03-08 数据库备份里的原始 banend（备份时还没被封禁的用户）；
--   2) 当前 users.banend（2026-03 之后注册的用户，通常就是注册时间）；
--   3) 最早活跃时间（帖子/评论/刷新令牌/币流水/邮箱验证），用于兜底。
--
-- 执行：mysql --default-character-set=utf8mb4 ...

-- 列由 AutoMigrate 创建；如果还没创建，先执行：
-- ALTER TABLE users ADD COLUMN registered_at datetime NULL AFTER banend;

CREATE TEMPORARY TABLE tmp_registered_at (
  user_id int NOT NULL PRIMARY KEY,
  registered_at datetime NOT NULL
) ENGINE=MEMORY;


UPDATE users u
JOIN tmp_registered_at t ON t.user_id = u.userID
SET u.registered_at = t.registered_at;

DROP TEMPORARY TABLE tmp_registered_at;

-- 按修正后的注册时间补发缺失的周年勋章（幂等）。
SELECT
  u.userID,
  b.badge_id,
  CONCAT('anniversary:', YEAR(u.registered_at), ':', y.n),
  'auto',
  CONCAT('注册周年补发：满 ', y.n, ' 年'),
  DATE_ADD(u.registered_at, INTERVAL y.n YEAR),
  NOW()
FROM users u
JOIN (SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3) y
JOIN badges b ON b.code = CONCAT('anniversary-', y.n) AND b.enabled = 1
WHERE u.registered_at IS NOT NULL
  AND TIMESTAMPDIFF(YEAR, u.registered_at, NOW()) >= y.n;

-- 防御性清理：如果历史上按错误日期发多了，按修正后的 registered_at 删除无效的自动周年勋章。
DELETE ub FROM user_badges ub
JOIN badges b ON b.badge_id = ub.badge_id
JOIN users u ON u.userID = ub.user_id
WHERE b.code LIKE 'anniversary-%'
  AND ub.source = 'auto'
  AND (u.registered_at IS NULL
       OR TIMESTAMPDIFF(YEAR, u.registered_at, NOW()) < CAST(SUBSTRING(b.code, 13) AS UNSIGNED));
